import { Component, OnInit } from '@angular/core';
import { Router } from '@angular/router';
import { IonicStorageService } from 'src/app/services/ionic-storage/ionic-storage.service';

@Component({
  selector: 'app-congratulation',
  templateUrl: './congratulation.page.html',
  styleUrls: ['./congratulation.page.scss'],
})
export class CongratulationPage implements OnInit {
  level: any;

  constructor( private router: Router, private ionicstoragess: IonicStorageService) { }

  ngOnInit() {
  }

  ionViewDidEnter() {

    this.levelData();

  }

 

  levelData() {
    this.ionicstoragess.getData('eetSurveyLevel').then(
      (dataa) => {
        if (dataa != null) {
          this.level = dataa
          console.log(this.level, 'levsczfsf');
        }
      },
      (error) => console.error(error)
    )
  }

  theEnd(){
    this.router.navigate(['/tabs/school-observation'])
  }
}
